-- Synthetic, rollback-only Pet Care and shared-boundary checks.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('7c100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','pet-a@example.test','',now(),'{}','{}',now(),now()),
('7c100000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','pet-b@example.test','',now(),'{}','{}',now(),now());
insert into organizations(id,name,slug,industry,pet_care_pilot_enabled,appointment_parallel_enabled) values
('7c200000-0000-4000-8000-000000000001','Milo Grooming Test','pet-a-test','pet_care',true,true),
('7c200000-0000-4000-8000-000000000002','Other Grooming Test','pet-b-test','pet_care',true,true);
insert into organization_subscriptions(organization_id,plan_id,status) select id,'pro','active' from organizations where id in('7c200000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000002');
insert into organization_memberships(organization_id,user_id,role) values('7c200000-0000-4000-8000-000000000001','7c100000-0000-4000-8000-000000000001','owner'),('7c200000-0000-4000-8000-000000000002','7c100000-0000-4000-8000-000000000002','owner');
insert into branches(id,organization_id,name,is_primary) values('7c300000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001','Main',true),('7c300000-0000-4000-8000-000000000002','7c200000-0000-4000-8000-000000000002','Other',true);
update branches set opening_hours=(select jsonb_object_agg(d,jsonb_build_object('open','00:00','close','23:59')) from unnest(array['monday','tuesday','wednesday','thursday','friday','saturday','sunday'])d) where id in('7c300000-0000-4000-8000-000000000001','7c300000-0000-4000-8000-000000000002');
insert into customers(id,organization_id,full_name) values('7c400000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001','Maria Test'),('7c400000-0000-4000-8000-000000000002','7c200000-0000-4000-8000-000000000002','Other Test');
insert into pet_profiles(id,organization_id,customer_id,name,species,handling_cautions) values('7c500000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001','7c400000-0000-4000-8000-000000000001','Milo','dog','INTERNAL_DO_NOT_EXPOSE'),('7c500000-0000-4000-8000-000000000002','7c200000-0000-4000-8000-000000000001','7c400000-0000-4000-8000-000000000001','Luna','cat',null),('7c500000-0000-4000-8000-000000000003','7c200000-0000-4000-8000-000000000002','7c400000-0000-4000-8000-000000000002','Other Pet','dog',null);
insert into organization_staff_profiles(id,organization_id,full_name,job_function) values('7c600000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001','Ana Test','Groomer'),('7c600000-0000-4000-8000-000000000002','7c200000-0000-4000-8000-000000000001','Bo Test','Groomer');
insert into services(id,organization_id,name,duration_minutes,base_price_centavos) values('7c700000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001','Bath and brush',60,50000);
insert into scheduling_resources(id,organization_id,branch_id,name,resource_type,capacity) values('7c800000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001','7c300000-0000-4000-8000-000000000001','Grooming Room','room',2);
create temporary table pet_test_ids(k text primary key,id uuid);
grant all on pet_test_ids to authenticated;
set local role authenticated;
set local "request.jwt.claims"='{"sub":"7c100000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*) from pet_profiles)::integer,2,'other tenant pets excluded');
select throws_ok($$insert into pet_profiles(organization_id,customer_id,name,species)values('7c200000-0000-4000-8000-000000000001','7c400000-0000-4000-8000-000000000002','Wrong owner','dog')$$,null,null,'cross-tenant owner rejected');
select throws_ok($$
update organizations set pet_care_pilot_enabled=false where id='7c200000-0000-4000-8000-000000000001'$$,null,null,'owner cannot toggle pilot');
insert into pet_test_ids values('first',save_pet_appointment('7c500000-0000-4000-8000-000000000001',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000001']::uuid[],date_trunc('day',now())+interval '2 days 2 hours',array['7c600000-0000-4000-8000-000000000001']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[]));
set constraints all immediate;
select ok((select vehicle_id is null from appointments where id=(select id from pet_test_ids where k='first')),'grooming appointment needs no vehicle');
select is((select expected_total_centavos from appointments where id=(select id from pet_test_ids where k='first')),50000::bigint,'server service price snapshot');
select throws_ok($$select save_pet_appointment('7c500000-0000-4000-8000-000000000001',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000001']::uuid[],date_trunc('day',now())+interval '2 days 2 hours',array['7c600000-0000-4000-8000-000000000002']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[])$$,null,null,'same pet cannot double book');
set constraints all deferred;
insert into pet_test_ids values('second',save_pet_appointment('7c500000-0000-4000-8000-000000000002',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000001']::uuid[],date_trunc('day',now())+interval '2 days 2 hours',array['7c600000-0000-4000-8000-000000000002']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[]));
set constraints all immediate;
select is((select count(*) from appointments where organization_id='7c200000-0000-4000-8000-000000000001')::integer,2,'different pets of same owner may overlap');
select is((select count(*) from pet_appointment_details)::integer,2,'failed write left no partial pet association');
select throws_ok($$select save_pet_appointment('7c500000-0000-4000-8000-000000000003',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000001']::uuid[],date_trunc('day',now())+interval '3 days 2 hours',array['7c600000-0000-4000-8000-000000000001']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[])$$,null,null,'cross-tenant pet booking rejected');
select lives_ok($$select record_appointment_payment((select id from pet_test_ids where k='first'),20000,'cash','pet-test-payment-1')$$,'appointment partial payment without Job Order');
select lives_ok($$select record_appointment_payment((select id from pet_test_ids where k='first'),20000,'cash','pet-test-payment-1')$$,'exact payment retry idempotent');
select is((select count(*) from payments where appointment_id=(select id from pet_test_ids where k='first'))::integer,1,'retry did not duplicate payment');
select throws_ok($$select record_appointment_payment((select id from pet_test_ids where k='first'),40000,'cash','pet-test-payment-over')$$,null,null,'overpayment rejected');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'confirm')$$,'confirm grooming');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'arrive')$$,'check in');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'start')$$,'start grooming');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'finish')$$,'finish grooming');
select is((select pickup_status from pet_appointment_details where appointment_id=(select id from pet_test_ids where k='first')),'not_ready','completion is not readiness or collection');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'ready')$$,'mark ready while a balance remains');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'ready')$$,'ready retry idempotent');
select lives_ok($$select record_appointment_payment((select id from pet_test_ids where k='first'),30000,'gcash','pet-test-payment-2')$$,'remaining payment');
select is((select pickup_status from pet_appointment_details where appointment_id=(select id from pet_test_ids where k='first')),'ready','payment does not mark collected');
select lives_ok($$select transition_pet_appointment((select id from pet_test_ids where k='first'),'collect')$$,'authorized collection');
select is((select collected_by from pet_appointment_details where appointment_id=(select id from pet_test_ids where k='first')),'7c100000-0000-4000-8000-000000000001'::uuid,'actor is authenticated operator, not unlinked groomer');
select lives_ok($$select create_appointment_self_service_link((select id from pet_test_ids where k='second'),repeat('a',64),now()+interval '7 days')$$,'create secure Pet appointment link');
reset role;
select is((select count(*) from notification_outbox where reference_id=(select id from pet_test_ids where k='first') and notification_type='PET_CARE_READY')::integer,2,'ready retries enqueue one message per channel');
select is((select count(*) from notification_outbox where reference_id=(select id from pet_test_ids where k='first') and notification_type='PET_CARE_READY' and status='cancelled')::integer,2,'missing customer contacts skip delivery safely');
set local role anon;
set local "request.jwt.claims"='{"role":"anon"}';
select throws_ok($$select * from pet_profiles$$,null,null,'anonymous pet directory denied');
select is(get_public_appointment_self_service(repeat('a',64))->>'petName','Luna','private link exposes only linked pet name');
select ok(get_public_appointment_self_service(repeat('a',64))::text not like '%INTERNAL_DO_NOT_EXPOSE%','public DTO excludes handling cautions');
select is(get_public_appointment_self_service(repeat('a',64))->'assignedStaff'->>0,'Bo Test','unlinked groomer displayed without fake account');
select is(update_public_appointment_self_service(repeat('a',64),'confirm',null,1)->>'state','confirmed','public confirmation');
select is(update_public_appointment_self_service(repeat('a',64),'confirm',null,1)->>'state','confirmed','confirmation retry idempotent');
select is(update_public_appointment_self_service(repeat('a',64),'reschedule',date_trunc('day',now())+interval '2 days 4 hours',1)->>'state','rescheduled','public reschedule uses existing assignments');
select is(update_public_appointment_self_service(repeat('a',64),'reschedule',date_trunc('day',now())+interval '2 days 5 hours',1)->>'state','unavailable','stale revision rejected');
select throws_ok($$select transition_pet_appointment('00000000-0000-4000-8000-000000000000','collect')$$,null,null,'public links cannot collect pets');
reset role;
set local "request.jwt.claims"='{}';
select is((select expected_total_centavos from appointments where id=(select id from pet_test_ids where k='second')),50000::bigint,'reschedule retains price snapshot');
select is((select count(*) from appointment_staff_assignments where appointment_id=(select id from pet_test_ids where k='second') and staff_profile_id='7c600000-0000-4000-8000-000000000002')::integer,1,'reschedule retains groomer');
select is((select count(*) from notification_outbox where reference_id=(select id from pet_test_ids where k='second') and notification_type='PET_CARE_CONFIRMATION' and status in('pending','processing'))::integer,0,'obsolete confirmation messages are not deliverable');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"7c100000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(pet_care_financial_summary('7c200000-0000-4000-8000-000000000001','7c300000-0000-4000-8000-000000000001')->>'outstandingCentavos','50000','dashboard balance reflects actual remaining appointment charges');
select is(pet_care_financial_summary('7c200000-0000-4000-8000-000000000001','7c300000-0000-4000-8000-000000000001')->>'paymentsCollectedTodayCentavos','50000','cash collection label uses actual payments today');
select throws_ok($$select pet_care_financial_summary('7c200000-0000-4000-8000-000000000002','7c300000-0000-4000-8000-000000000002')$$,null,null,'financial summary rejects other tenant');
reset role;
set local "request.jwt.claims"='{}';
update customers set email='owner@example.test' where id='7c400000-0000-4000-8000-000000000001';
insert into customer_communication_preferences(customer_id,organization_id,email_opt_in,sms_opt_in) values('7c400000-0000-4000-8000-000000000001','7c200000-0000-4000-8000-000000000001',true,false) on conflict(customer_id) do update set email_opt_in=true;
set local role authenticated;
set local "request.jwt.claims"='{"sub":"7c100000-0000-4000-8000-000000000001","role":"authenticated"}';
select lives_ok($$select create_appointment_self_service_link((select id from pet_test_ids where k='second'),repeat('b',64),now()+interval '7 days','cipher','iv','tag')$$,'new private link uses the shared encrypted delivery-secret store');
reset role;
set local "request.jwt.claims"='{}';
select is(enqueue_pet_care_message((select id from pet_test_ids where k='second'),'reminder'),1,'eligible owner email reminder queued');
select is(enqueue_pet_care_message((select id from pet_test_ids where k='second'),'reminder'),0,'same reminder generation is deduplicated');
select ok((select bool_and(pet_care_notification_is_current(id)) from notification_outbox where reference_id=(select id from pet_test_ids where k='second') and status='pending'),'current messages pass final visit eligibility');
update appointments set starts_at=starts_at+interval '1 hour' where id=(select id from pet_test_ids where k='second');
select is((select count(*) from notification_outbox where reference_id=(select id from pet_test_ids where k='second') and status='pending')::integer,0,'rescheduling cancels genuinely pending messages');
select ok((select not bool_or(pet_care_notification_is_current(id)) from notification_outbox where reference_id=(select id from pet_test_ids where k='second')),'old schedule messages fail final eligibility');
select is(enqueue_pet_care_message((select id from pet_test_ids where k='second'),'reminder'),1,'rescheduled appointment receives a replacement reminder');
select is(enqueue_pet_care_message((select id from pet_test_ids where k='first'),'ready'),0,'collected pets cannot produce another ready message');
-- Adjacent bookings occupy different portions of a two-hour candidate.
insert into pet_profiles(id,organization_id,customer_id,name,species) values('7c500000-0000-4000-8000-000000000004','7c200000-0000-4000-8000-000000000001','7c400000-0000-4000-8000-000000000001','Kiwi','dog');
insert into organization_staff_profiles(id,organization_id,full_name,job_function) values('7c600000-0000-4000-8000-000000000003','7c200000-0000-4000-8000-000000000001','Cora Test','Groomer');
insert into services(id,organization_id,name,duration_minutes,base_price_centavos) values('7c700000-0000-4000-8000-000000000002','7c200000-0000-4000-8000-000000000001','Long grooming',120,80000);
set local role authenticated;
set local "request.jwt.claims"='{"sub":"7c100000-0000-4000-8000-000000000001","role":"authenticated"}';
set constraints all deferred;
insert into pet_test_ids values('early',save_pet_appointment('7c500000-0000-4000-8000-000000000001',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000001']::uuid[],date_trunc('day',now())+interval '12 days 2 hours',array['7c600000-0000-4000-8000-000000000001']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[]));
insert into pet_test_ids values('late',save_pet_appointment('7c500000-0000-4000-8000-000000000002',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000001']::uuid[],date_trunc('day',now())+interval '12 days 3 hours',array['7c600000-0000-4000-8000-000000000002']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[]));
insert into pet_test_ids values('long',save_pet_appointment('7c500000-0000-4000-8000-000000000004',null,'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000002']::uuid[],date_trunc('day',now())+interval '12 days 2 hours',array['7c600000-0000-4000-8000-000000000003']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[]));
set constraints all immediate;
select ok(exists(select 1 from pet_test_ids where k='long'),'capacity two permits long appointment across two adjacent occupied segments');
select lives_ok($$select save_pet_appointment('7c500000-0000-4000-8000-000000000004',(select id from pet_test_ids where k='long'),'7c300000-0000-4000-8000-000000000001',array['7c700000-0000-4000-8000-000000000002']::uuid[],date_trunc('day',now())+interval '12 days 2 hours',array['7c600000-0000-4000-8000-000000000003']::uuid[],array['7c800000-0000-4000-8000-000000000001']::uuid[])$$,'editing excludes its own occupancy');
select throws_ok($$delete from appointment_staff_assignments where appointment_id=(select id from pet_test_ids where k='long')$$,null,null,'active Pet booking cannot lose its required groomer');
select throws_ok($$delete from appointment_resource_assignments where appointment_id=(select id from pet_test_ids where k='long')$$,null,null,'active Pet booking cannot lose its required resource');
reset role;
set local "request.jwt.claims"='{}';
select is(appointment_resource_peak('7c800000-0000-4000-8000-000000000001',date_trunc('day',now())+interval '12 days 2 hours',date_trunc('day',now())+interval '12 days 4 hours',(select id from pet_test_ids where k='long')),1::bigint,'SQL peak is one, not the sum of both adjacent bookings');
update organizations set status='suspended' where id='7c200000-0000-4000-8000-000000000001';
set local role authenticated;
set local "request.jwt.claims"='{"sub":"7c100000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*) from pet_profiles)::integer,3,'suspension preserves record access');
select throws_ok($$insert into pet_profiles(organization_id,customer_id,name,species)values('7c200000-0000-4000-8000-000000000001','7c400000-0000-4000-8000-000000000001','Disabled','dog')$$,null,null,'suspended business cannot create pets');
select is(get_public_appointment_self_service(repeat('a',64))->>'state','invalid','suspension closes public capability');
select * from finish();
rollback;
